                        lienPrincipal.sourceReferenceNumber = pastDuePrincipal.PARENT_PASTDUECODE;
                        lienPrincipal.lienAmount = pastDuePrincipal.DEBITAMOUNT;
                        lienPrincipal.branchId = item.branchId;
                        lienPrincipal.companyId = item.companyId;
