                        if (result == true)
                        {
                            updateLoanReviewOperation(loanReviewOperationsId, loanId);
                            updateLoanPrincipalInterestPaymentDate(model.interestFirstpaymentDate, model.principalFirstpaymentDate, loanId);
                            output = true;
                        }
                        else
                        {
                            output = false;
                        }


